import { test, expect } from '@playwright/test';

test.describe('Breadcrumb Navigation', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://example.com'); // Replace with the actual URL
  });

  test('should display breadcrumbs on the homepage', async ({ page }) => {
    const breadcrumb = page.getByRole('navigation', { name: /breadcrumb/i });
    await expect(breadcrumb).toBeVisible();
    await expect(breadcrumb).toContainText('Home');
  });

  test('should update breadcrumbs when navigating to a subpage', async ({ page }) => {
    await page.getByText('About Us').click(); // Replace with the actual link text
    const breadcrumb = page.getByRole('navigation', { name: /breadcrumb/i });
    await expect(breadcrumb).toBeVisible();
    await expect(breadcrumb).toContainText('Home');
    await expect(breadcrumb).toContainText('About Us');
  });
});
